source.exploreUrl:
@js:
	java.toast("\n 正在进行发现页热更新...");
eval(String(source.loginUrl));
let URL = Get('urls')[Get('ci')];
let list = [];

const push = (title, url, size) => list.push({
	"title": title,
	"url": url,
	"style": {
		"layout_flexGrow": 1,
		"layout_flexBasisPercent": size
	}
});

const request = org.jsoup.Jsoup.parse(java.ajax(URL));
const aElements = request.select("li.hidden-md:nth-of-type(6) a");
const sj = aElements.length > 0 ? aElements[0].attr('href').trim() : "";

const authInfo = JSON.parse(source.getLoginInfo());
const username = authInfo?.['账号'] || "寿横";
const password = authInfo?.['密码'] || "";

if (username && password) {
	const a = java.ajax(URL + '/login');
	const b = a.match(username)?.[0] || "";
	if (b == "") {
		Login();
	} else {
		java.toast("\n 欢迎主人 " + b);
	}
}

const label = sortNames[Get('tag1')];
const sort = sortKeys[Get('tag1')];
const _label = categoryNames[Get('tag2')];
const _sort = categoryPaths[Get('tag2')];

push('[▶ ' + username + ' ◀]', '', 1);
push('→ ' + URL + '  分流' + SH[Get('shunt')], '', 1);
push(
	sj ? "随机" : "❗❗该链接不可用，请更换链接，然后刷新❗❗",
	`${URL}${sj}`,
	1
);

push('漫画观看记录', URL + '/user/' + username + '/favorite/watchlist', 0.45);
push('小说观看记录', URL + '/user/' + username + '/favorite/novel_watchlist', 0.45);

const today = new Date();
const day = today.getDay() === 0 ? 7 : today.getDay();
const dayOfWeek = weekDays[today.getDay()].D;
push('本日连载 - ' + dayOfWeek, Get('url') + '/serialization/' + day, 1);
weekDays.map(({
	D,
	N
}) => {
	push(D, `${URL}/serialization/${N}`, 0.25);
});

push(`🏷️标签--按${label}--${_label}🏷️`, `${URL}/albums${_sort}?o=${sort}&page={{page}}`, 1);
_list.map(([t, u]) => {
	push(t, `${URL}/${u}${_sort}?o=${sort}&page={{page}}`, 0.25);
});

push('┡其他类┦', `${URL}/albums/another?o=${sort}&page={{page}}`, 1);
__list.map(([t, u]) => {
	push(t, `${URL}/${u}?o=${sort}&page={{page}}`, 0.25);
});

push('┡排行榜┦', '', 1);
typeList.map(([t, type]) => {
	push(t, `${URL}/albums${_sort}?o=${sort}${type}&page={{page}}`, 0.2);
});

push('▶主题A漫◀', '', 1);
sorts1.forEach(s => {
	push(s, `${URL}/search/photos${_sort}?search_query=${s}&o=${sort}&page={{page}}`, 0.25);
});

push('▶角色/扮演◀', '', 1);
sorts2.forEach(s => {
	push(s, `${URL}/search/photos${_sort}?search_query=${s}&o=${sort}&page={{page}}`, 0.25);
});

push('▶特殊PLAY◀', '', 1);
sorts3.forEach(s => {
	push(s, `${URL}/search/photos${_sort}?search_query=${s}&o=${sort}&page={{page}}`, 0.25);
});

push('▶其他◀', '', 1);
sorts4.forEach(s => {
	push(s, `${URL}/search/photos${_sort}?search_query=${s}&o=${sort}&page={{page}}`, 0.25);
});

JSON.stringify(list);

